const recordReminderSent = `-- name: RecordReminderSent :execrows
INSERT INTO mentor_booking_reminders (booking_id, offset_minutes)
VALUES ($1, $2)
ON CONFLICT DO NOTHING
`

type RecordReminderSentParams struct {
	BookingID     pgtype.UUID `json:"booking_id"`
	OffsetMinutes int32       `json:"offset_minutes"`
}

// Claim one reminder. ON CONFLICT DO NOTHING means a concurrent run inserts nothing and
// gets zero rows back — so this is the CLAIM, and a caller that sends before checking the
// row count sends twice. Send after this returns 1, never before.
func (q *Queries) RecordReminderSent(ctx context.Context, arg RecordReminderSentParams) (int64, error) {
	result, err := q.db.Exec(ctx, recordReminderSent, arg.BookingID, arg.OffsetMinutes)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

